            left = node_index * 2 + 1
            right = left + 1
            if left < len(pool.free):
                heapq.heappush(
                    heap_nodes, (pool.free[left], left)
                )
            if right < len(pool.free):
                heapq.heappush(
                    heap_nodes, (pool.free[right], right)
                )
            return value

        dynamic_head[0] = _advance_dynamic()

        def dynamic_candidate():
            return dynamic_head[0]

        def consume_dynamic():
            value = dynamic_head[0]
            sim_rented.add(value)
            dynamic_head[0] = _advance_dynamic()
            return value

    items = []
    for queued_sid in window:
        entry = capacity_queue[queued_sid]
        user = entry[0]
        order = entry[4]
        if entry[3] <= now_ms:
            items.append(
                {
                    "会话": queued_sid,
                    "用户": user,
                    "入队序": order,
                    "结果": _CAP_TIMEOUT,
                    "原因": "截止",
                }
            )
            continue

        # 等待原因按全局/用户/模板/无池/池故障/地址取首个受阻项；全部
        # 闸口通过且可取址才晋升，晋升占用即时影响后项。
        template_id = self._user_templates.get(user)
        session_limit = (
            self._templates[template_id][3]
            if template_id is not None
            else 0
        )
        if total_count >= self._total:
            result, reason = "等待", "全局"
        elif per_user.get(user, 0) >= self._per:
            result, reason = "等待", "用户"
        elif (
            session_limit
            and per_template.get(template_id, 0) >= session_limit
        ):
            result, reason = "等待", "模板"
        elif pool is None:
            result, reason = "等待", "无池"
        elif self._pool_is_exhausted(_DEFAULT_POOL_ID, now_ms):
            result, reason = "等待", "池故障"
        else:
            static_ip = pool.static.get(user)
            if static_ip is None:
                ip_int = dynamic_candidate()
            elif static_ip in sim_rented:
                # 专属静态址已租用：不回落动态址。
                ip_int = None
            else:
                ip_int = static_ip
            if ip_int is None:
                result, reason = "等待", "地址"
            else:
                if static_ip is None:
                    consume_dynamic()
                else:
                    sim_rented.add(static_ip)
                total_count += 1
                per_user[user] = per_user.get(user, 0) + 1
                if template_id is not None:
                    per_template[template_id] = (
                        per_template.get(template_id, 0) + 1
                    )
                result, reason = _CAP_PROMOTED, ""
        items.append(
            {
                "会话": queued_sid,
                "用户": user,
                "入队序": order,
                "结果": result,
                "原因": reason,
            }
        )

    payload = {
        "时刻": now_ms,
        "剩余": total_queue - len(items),
        "项目": items,
    }
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":")) + "\n"

