        else: assert i["原因"] in ("全局","用户","模板","无池","池故障","地址")
    # 与真实推进比集合（窗口含全队时）
    if len(s._queue_order)<=limit:
        snap=copy.deepcopy(s)
        adv=json.loads(snap.capacity("adv","推进","",None,now))
        fP={i["入队序"] for i in fc["项目"] if i["结果"]=="晋升"}
        fT={i["入队序"] for i in fc["项目"] if i["结果"]=="超时"}
        if fP|fT!=set(adv["变更"]):
            bad+=1; print("DIFF",trial,sorted(fP),sorted(fT),sorted(adv["变更"])); break
print("diff:",bad,"mutation:",mut,"/ 8000")
